3	const DEDUCTIBLE_PER_DAMAGE_ENTRY = 100;
4	const PAYOUT_CAP_MULTIPLE = 2;
5	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
6	const HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE = 0.5;
7	const FULL_REIMBURSEMENT_SHARE = 1;
8	
9	export interface Damage {
10	  readonly itemType: string;
11	  readonly amount: number;
12	}
13	
14	export interface Incident {
15	  readonly cause: string;
16	  readonly damages: readonly Damage[];
17	}
18	
19	export interface Policy {
20	  readonly items: readonly Item[];
21	  readonly insuranceSum: number;
22	  remainingCap: number;
23	}
24	
25	export interface ClaimSettlement {
26	  readonly payout: number;
27	  readonly remainingCap: number;
28	}
29	
30	// A damage entry names an insured item by type; the clauses that govern the
31	// payout are properties of that insured item, not of the damage report.
32	function damagedItemFor(policy: Policy, damage: Damage): Item {
33	  const damagedItem = policy.items.find((item) => item.type === damage.itemType);
34	  if (damagedItem === undefined) {
35	    throw new Error(`damaged item ${damage.itemType} is not covered by the policy`);
36	  }
37	  return damagedItem;
38	}
39	
40	function roundPayoutInOfficesFavour(payout: number): number {
41	  return Math.floor(payout);
42	}
43	
44	export function policyFor(items: readonly Item[]): Policy {
45	  const insuranceSum = insuranceSumOf(items);
46	  return { items, insuranceSum, remainingCap: insuranceSum * PAYOUT_CAP_MULTIPLE };
47	}
48	
49	// Damage to an item with enchantment level >= 8 is reimbursed at 50 % of the
50	// damage amount; otherwise the damage is reimbursed in full. The share is taken
51	// before the deductible.
52	function reimbursableShareOf(damagedItem: Item): number {
53	  return (damagedItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
54	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_SHARE
55	    : FULL_REIMBURSEMENT_SHARE;
56	}
57	
58	// One entry of the incident's `damages` array is one damage, and each one bears
59	// its own deductible -- a single dragon attack that damages a sword and an amulet
60	// deducts 100 G twice, not once.
61	function reimbursementFor(damage: Damage, damagedItem: Item): number {
62	  return damage.amount * reimbursableShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE_ENTRY;
63	}
64	
65	// Summing per entry is what makes the deductible per-entry: the incident as a
66	// whole is never the unit the deductible is charged against.
67	function desiredReimbursementFor(policy: Policy, incident: Incident): number {
68	  return incident.damages.reduce(
69	    (sum, damage) => sum + reimbursementFor(damage, damagedItemFor(policy, damage)),
70	    0,
71	  );
72	}
73	
74	// The cap limits what a single claim pays out, and every payout consumes it:
75	// successive claims against the same policy share one cap.
76	function payoutLimitedToRemainingCap(desiredReimbursement: number, remainingCap: number): number {
77	  return Math.min(desiredReimbursement, remainingCap);
78	}
79	
80	function consumeCap(policy: Policy, payout: number): void {
81	  policy.remainingCap -= payout;
82	}
83	
84	export function settle(policy: Policy, incident: Incident): ClaimSettlement {
85	  const payout = roundPayoutInOfficesFavour(
86	    payoutLimitedToRemainingCap(desiredReimbursementFor(policy, incident), policy.remainingCap),
87	  );
88	  consumeCap(policy, payout);
89	  return { payout, remainingCap: policy.remainingCap };
90	}
